#!/usr/bin/env bash
# ============================================================================
# Shared check library for agent_core.nvim.
#
# Single source of truth for security, secret, format, and smoke-test gates.
# Consumed by BOTH layers of the pipeline so they can never drift:
#
#   Local git hooks (.githooks/*)      → fast feedback before code leaves the
#                                        developer machine.
#   GitHub Actions (.github/workflows) → authoritative re-run on every push and
#                                        PR, on ubuntu + windows runners.
#
# Each function is small, focused, and returns nonzero on failure so the
# caller can aggregate a FAILED count. Hooks and the CI runner pick the subset
# relevant to their stage.
#
#   pre-commit   → fast, staged-file-scoped checks
#   commit-msg   → message format only
#   pre-push     → full-repo + new-commit-range checks
#   CI (Actions) → run_ci_security / run_ci_lint / run_ci_smoke runners
# ============================================================================

# ── output helpers ─────────────────────────────────────────────────────────
hook_pass() { echo "PASS  $*"; }
hook_fail() { echo "FAIL  $*"; }
hook_warn() { echo "WARN  $*"; }
hook_info() { echo "  ->  $*"; }

# Lua source files in scope (tracked). Centralised so every check uses the
# same file set.
lua_files() { git ls-files '*.lua'; }

# ── commit message format (Conventional Commits) ───────────────────────────
check_commit_subject() {
  local msg="$1"
  if ! echo "$msg" | grep -iE "^(ADD|MOD|REMOVE|FIX|DOCS|TEST|REFACTOR|PERF|CI|CHORE|FEAT|STYLE|BUILD|REVERT)(\([a-z0-9/_\-]+\))?:" >/dev/null; then
    hook_fail "Invalid commit format: $msg"
    echo "   Expected: TYPE(SCOPE): subject"
    echo "   Types: ADD MOD REMOVE FIX DOCS TEST REFACTOR PERF CI CHORE FEAT STYLE BUILD REVERT"
    return 1
  fi
  if [ ${#msg} -gt 120 ]; then
    hook_fail "Subject too long (${#msg} > 120 chars)"
    return 1
  fi
  return 0
}

# Validate all non-merge commits in a git rev-list range ($1).
check_commits_range() {
  local range="$1"
  [ -z "$range" ] && { hook_warn "No commit range — skipping message validation"; return 0; }
  hook_info "Commit messages in range: $range"
  local commits c msg failed=0
  local exclude_ref=""
  if [ -n "${CI_BASE_SHA:-}" ]; then
    exclude_ref="$CI_BASE_SHA"
  elif git rev-parse --verify origin/main >/dev/null 2>&1; then
    exclude_ref="origin/main"
  fi
  local exclude_args=""
  if [ -n "$exclude_ref" ]; then
    exclude_args="--not $exclude_ref"
  fi
  commits=$(git rev-list --no-merges $range $exclude_args 2>/dev/null || true)
  if [ -z "$commits" ]; then
    hook_pass "No non-merge commits to validate"
    return 0
  fi
  for c in $commits; do
    msg=$(git log -1 --format=%s "$c")
    check_commit_subject "$msg" || failed=$((failed + 1))
  done
  if [ $failed -gt 0 ]; then
    hook_fail "$failed commit message(s) failed validation"
    return 1
  fi
  hook_pass "Commit messages OK"
  return 0
}

run_ci_commits() {
  local range=""
  case "${CI_EVENT_NAME:-}" in
    pull_request)
      range="${CI_BASE_SHA:-}..${CI_HEAD_SHA:-}"
      ;;
    push)
      if [ "${CI_BEFORE_SHA:-}" = "0000000000000000000000000000000000000000" ] || [ -z "${CI_BEFORE_SHA:-}" ]; then
        range="${CI_SHA:-}"
      else
        range="${CI_BEFORE_SHA:-}..${CI_SHA:-}"
      fi
      ;;
    *)
      hook_warn "Unknown CI_EVENT_NAME — skipping commit validation"
      return 0
      ;;
  esac
  check_commits_range "$range"
}

# ── .env / secret-file tracking ────────────────────────────────────────────
check_no_env_tracked() {
  if git ls-files | grep -E '(^|/)\.env(\.|$)' | grep -qv '\.example$'; then
    hook_fail ".env file is tracked by git — credentials may be exposed"
    git ls-files | grep -E '(^|/)\.env(\.|$)' | grep -v '\.example$'
    echo "   Remove with: git rm --cached <file> && commit"
    return 1
  fi
  hook_pass ".env files not tracked"
  return 0
}

check_no_env_staged() {
  if git diff --cached --name-only --diff-filter=A | grep -E '(^|/)\.env(\.|$)' | grep -qv '\.example$'; then
    hook_fail "Staged .env file — unstage with: git restore --staged .env*"
    return 1
  fi
  return 0
}

# agent_keys.json is the plugin's 0600 secret store — must never be tracked.
check_no_keys_json_tracked() {
  if git ls-files | grep -qE '(^|/)agent_keys\.json$'; then
    hook_fail "agent_keys.json is tracked — it holds API keys and must stay local"
    return 1
  fi
  hook_pass "agent_keys.json not tracked"
  return 0
}

# The indexer output is generated; it must never be committed.
check_no_avante_md_tracked() {
  if git ls-files | grep -qE '(^|/)AVANTE\.md$'; then
    hook_fail "AVANTE.md is tracked — it is generated by :AgentIndex and should be gitignored"
    return 1
  fi
  hook_pass "AVANTE.md not tracked"
  return 0
}

# ── .gitignore must protect secrets/scratch (meta-check, defense in depth) ──
check_gitignore_protects_secrets() {
  local missing=0
  [ -f .gitignore ] || { hook_fail ".gitignore missing"; return 1; }
  grep -Eq '(^|/)\.env(\b|$)|\*\.env|\.env\.\*' .gitignore || { hook_fail ".gitignore does not ignore .env"; missing=1; }
  grep -Eq 'agent_keys\.json' .gitignore || { hook_fail ".gitignore does not ignore agent_keys.json"; missing=1; }
  grep -Eq 'AVANTE\.md' .gitignore || { hook_fail ".gitignore does not ignore AVANTE.md"; missing=1; }
  [ $missing -eq 0 ] && hook_pass ".gitignore protects secrets and generated output"
  return $missing
}

# ── Hardcoded secrets in Lua (OWASP A05 / CWE-798) ─────────────────────────
# Scope: $1 = "staged" | "tracked". Greps for high-risk identifiers assigned a
# non-empty literal. `api_key_name = "DEEPSEEK_API_KEY"` does NOT match because
# the identifier is `api_key_name`, not `api_key` (no lookahead needed: `=` must
# follow the identifier directly).
check_hardcoded_secrets() {
  local scope="${1:-tracked}" files failed=0
  if [ "$scope" = "staged" ]; then
    files=$(git diff --cached --name-only --diff-filter=AM | grep -E '\.lua$' || true)
    [ -z "$files" ] && return 0
  else
    files=$(lua_files)
  fi

  local pat='(api_key|apikey|password|passwd|secret|token|access_key|private_key|auth_token|client_secret)[[:space:]]*=[[:space:]]*["'"'"'][^"'"'"'$<{][^"'"'"']{3,}'

  if echo "$files" | xargs grep -En "$pat" 2>/dev/null \
      | grep -vEi '(os\.getenv|vim\.fn\.getenv|getenv|example|placeholder|changeme|change-this|your[-_]|xxx|REDACTED|api_key_name|stdpath)' \
      | grep -q .; then
    hook_fail "Possible hardcoded secret — credentials belong in the environment, never in source (OWASP A05 / CWE-798)"
    echo "$files" | xargs grep -En "$pat" 2>/dev/null \
      | grep -vEi '(os\.getenv|vim\.fn\.getenv|getenv|example|placeholder|changeme|change-this|your[-_]|xxx|REDACTED|api_key_name|stdpath)'
    failed=1
  fi

  # Known credential shapes that must never reach a committed file.
  if echo "$files" | xargs grep -EnI 'sk-[a-zA-Z0-9]{12,}|AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|ghp_[a-zA-Z0-9]{20,}' 2>/dev/null | grep -q .; then
    hook_fail "Static credential or private key material detected"
    echo "$files" | xargs grep -EnI 'sk-[a-zA-Z0-9]{12,}|AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|ghp_[a-zA-Z0-9]{20,}' 2>/dev/null
    failed=1
  fi

  [ $failed -eq 0 ] && hook_pass "No hardcoded secrets"
  return $failed
}

# ── Sensitive values must not be logged (OWASP A09) ────────────────────────
check_log_sensitive_lua() {
  local files; files=$(lua_files)
  if echo "$files" | xargs grep -En '(vim\.notify|print|vim\.print)\([^)]*(password|passwd|secret|api_key|apikey|token|private_key)' 2>/dev/null | grep -q .; then
    hook_fail "Sensitive value appears in a log/notify call (OWASP A09)"
    echo "$files" | xargs grep -En '(vim\.notify|print|vim\.print)\([^)]*(password|passwd|secret|api_key|apikey|token|private_key)' 2>/dev/null
    return 1
  fi
  hook_pass "Logging audit passed"
  return 0
}

# ── stylua ─────────────────────────────────────────────────────────────────
check_stylua_staged() {
  command -v stylua >/dev/null 2>&1 || { hook_warn "stylua not installed — skipping"; return 0; }
  local files
  files=$(git diff --cached --name-only --diff-filter=AM | grep '\.lua$' || true)
  [ -z "$files" ] && return 0
  if ! stylua --check $files 2>&1; then
    hook_fail "Unformatted Lua files — run: stylua lua/"
    return 1
  fi
  hook_pass "stylua clean (staged)"
  return 0
}

check_stylua_all() {
  command -v stylua >/dev/null 2>&1 || { hook_fail "stylua required — install with scripts/setup-dev.sh"; return 1; }
  local files; files=$(lua_files)
  [ -z "$files" ] && { hook_pass "no Lua files"; return 0; }
  if ! stylua --check $files 2>&1; then
    hook_fail "Unformatted Lua files — run: stylua lua/"
    return 1
  fi
  hook_pass "stylua clean"
  return 0
}

# ── selene ─────────────────────────────────────────────────────────────────
check_selene() {
  command -v selene >/dev/null 2>&1 || { hook_fail "selene required — install with scripts/setup-dev.sh"; return 1; }
  if ! selene lua 2>&1; then
    hook_fail "selene reported lints"
    return 1
  fi
  hook_pass "selene clean"
  return 0
}

# ── headless nvim smoke test ───────────────────────────────────────────────
check_smoke_nvim() {
  local nvim_bin="${NVIM_BIN:-nvim}"
  if ! command -v "$nvim_bin" >/dev/null 2>&1; then
    for p in /opt/nvim-linux-x86_64/bin/nvim /usr/local/bin/nvim; do
      [ -x "$p" ] && nvim_bin="$p" && break
    done
  fi
  command -v "$nvim_bin" >/dev/null 2>&1 || { hook_fail "nvim not found — set NVIM_BIN"; return 1; }

  local out
  out=$("$nvim_bin" --headless -u tests/minimal_init.lua \
    "+lua require('agent_core').setup(); assert(vim.fn.exists(':AgentMode') == 2, 'AgentMode command missing'); assert(vim.fn.exists(':AgentRecommend') == 2, 'AgentRecommend command missing'); assert(vim.fn.exists(':AgentRecommendToggle') == 2, 'AgentRecommendToggle command missing'); assert(vim.fn.exists(':AgentAutoSwitch') == 2, 'AgentAutoSwitch command missing'); assert(vim.fn.exists(':AgentAutoSwitchToggle') == 2, 'AgentAutoSwitchToggle command missing'); assert(vim.fn.exists(':AgentWorkspaceAdd') == 2, 'AgentWorkspaceAdd command missing'); assert(vim.fn.exists(':AgentWorkspaceRemove') == 2, 'AgentWorkspaceRemove command missing'); assert(vim.fn.exists(':AgentWorkspaceScan') == 2, 'AgentWorkspaceScan command missing'); assert(vim.fn.exists(':AgentWorkspaceList') == 2, 'AgentWorkspaceList command missing'); assert(vim.fn.exists(':AgentWorkspaceSwitch') == 2, 'AgentWorkspaceSwitch command missing'); assert(type(require('agent_core').get_mode_prompt) == 'function'); assert(type(require('agent_core').get_workspace_prompt) == 'function', 'get_workspace_prompt missing'); assert(type(require('agent_core.modes').all()) == 'table'); assert(type(require('agent_core.multitask').run_agent_tool) == 'function'); local w = require('agent_core.workspace'); assert(type(w) == 'table', 'workspace module missing'); assert(type(w.get_workspace_prompt) == 'function', 'workspace.get_workspace_prompt missing'); assert(type(w.list) == 'function', 'workspace.list missing'); local mi = require('agent_core.mcp_index'); assert(type(mi) == 'table', 'mcp_index module missing'); assert(type(mi.write_global) == 'function', 'mcp_index.write_global missing'); assert(type(mi.index_all) == 'function', 'mcp_index.index_all missing'); local idx = require('agent_core.indexer'); assert(type(idx.root_for) == 'function', 'indexer.root_for missing'); assert(type(idx.file_list_for) == 'function', 'indexer.file_list_for missing'); assert(type(idx.summary_for) == 'function', 'indexer.summary_for missing'); local r = require('agent_core.recommend'); assert(type(r) == 'table', 'recommend module missing'); assert(type(r.heuristic_classify) == 'function'); assert(r.heuristic_classify('fix the bug').mode == 'debug', 'fix -> debug'); assert(r.heuristic_classify('implement login').mode == 'agent', 'implement -> agent'); assert(r.heuristic_classify('explain this code').mode == 'ask', 'explain -> ask'); local a = require('agent_core.autoswitch'); assert(type(a) == 'table', 'autoswitch module missing'); assert(type(a.heuristic_classify) == 'function'); assert(a.heuristic_classify('implement the login feature').profile == 'DeepSeek (cloud)', 'implement -> DeepSeek'); assert(a.heuristic_classify('summarize this long document').profile == 'Gemini', 'summarize -> Gemini'); assert(a.heuristic_classify('review the security and architecture').profile == 'Claude', 'review -> Claude'); local c = require('agent_core.coordinator'); assert(type(c) == 'table', 'coordinator module missing'); assert(type(c.present) == 'function', 'coordinator.present missing'); assert(type(c.evaluate) == 'function', 'coordinator.evaluate missing'); print('AGENT_CORE_SMOKE_OK')" +qa 2>&1)
  if echo "$out" | grep -q 'AGENT_CORE_SMOKE_OK'; then
    hook_pass "headless nvim smoke test passed"
    return 0
  fi
  hook_fail "headless nvim smoke test failed"
  echo "$out"
  return 1
}

# ── detect-secrets ─────────────────────────────────────────────────────────
check_detect_secrets() {
  command -v detect-secrets >/dev/null 2>&1 || { hook_warn "detect-secrets not installed — skipping"; return 0; }
  [ -f .secrets.baseline ] || { hook_warn ".secrets.baseline missing — skipping"; return 0; }
  hook_info "detect-secrets scan..."
  local tmpbaseline
  tmpbaseline=$(mktemp)
  cp .secrets.baseline "$tmpbaseline"
  if ! detect-secrets scan --baseline "$tmpbaseline" >/dev/null 2>&1; then
    rm -f "$tmpbaseline"
    hook_fail "New secrets detected vs .secrets.baseline"
    echo "   Audit: detect-secrets audit .secrets.baseline"
    return 1
  fi
  rm -f "$tmpbaseline"
  hook_pass "No new secrets (detect-secrets)"
  return 0
}

check_detect_secrets_staged() {
  command -v detect-secrets >/dev/null 2>&1 || return 0
  [ -f .secrets.baseline ] || return 0
  local staged
  staged=$(git diff --cached --name-only --diff-filter=AM)
  [ -z "$staged" ] && return 0
  hook_info "detect-secrets on staged files..."
  local tmpbaseline
  tmpbaseline=$(mktemp)
  cp .secrets.baseline "$tmpbaseline"
  if ! echo "$staged" | xargs detect-secrets scan --baseline "$tmpbaseline" >/dev/null 2>&1; then
    rm -f "$tmpbaseline"
    hook_fail "Staged files contain new secrets (detect-secrets)"
    return 1
  fi
  rm -f "$tmpbaseline"
  hook_pass "No new secrets in staged files (detect-secrets)"
  return 0
}

check_detect_secrets_ci() {
  command -v detect-secrets >/dev/null 2>&1 || { hook_fail "detect-secrets required in CI — pip install detect-secrets"; return 1; }
  [ -f .secrets.baseline ] || { hook_fail ".secrets.baseline not committed — run: detect-secrets scan > .secrets.baseline"; return 1; }
  check_detect_secrets
}

# ── gitleaks full-history secret scan (advisory in hooks, separate in CI) ──
check_gitleaks() {
  command -v gitleaks >/dev/null 2>&1 || { hook_warn "gitleaks not installed — skipping (CI runs it)"; return 0; }
  hook_info "gitleaks detect..."
  if ! gitleaks detect --no-banner --redact 2>&1; then hook_fail "gitleaks found secrets"; return 1; fi
  hook_pass "gitleaks clean"
  return 0
}

# ============================================================================
# Aggregate runners — used by GitHub Actions so the server re-runs the exact
# same gate logic as the local hooks (no drift, defense in depth).
# ============================================================================

run_ci_security() {
  local FAILED=0
  echo "== CI security gate =="
  check_no_env_tracked            || FAILED=$((FAILED + 1))
  check_no_keys_json_tracked      || FAILED=$((FAILED + 1))
  check_no_avante_md_tracked      || FAILED=$((FAILED + 1))
  check_gitignore_protects_secrets || FAILED=$((FAILED + 1))
  check_hardcoded_secrets         || FAILED=$((FAILED + 1))
  check_log_sensitive_lua         || FAILED=$((FAILED + 1))
  check_detect_secrets_ci         || FAILED=$((FAILED + 1))
  echo "== CI security gate: $FAILED failure(s) =="
  return $FAILED
}

run_ci_lint() {
  local FAILED=0
  echo "== CI lint gate =="
  check_stylua_all || FAILED=$((FAILED + 1))
  check_selene     || FAILED=$((FAILED + 1))
  echo "== CI lint gate: $FAILED failure(s) =="
  return $FAILED
}

run_ci_smoke() {
  local FAILED=0
  echo "== CI smoke gate =="
  check_smoke_nvim || FAILED=$((FAILED + 1))
  echo "== CI smoke gate: $FAILED failure(s) =="
  return $FAILED
}

# Allow `bash .githooks/lib/checks.sh <function>` invocation from CI YAML.
if [ "${BASH_SOURCE[0]}" = "${0}" ] && [ $# -gt 0 ]; then
  "$@"
fi
